  const mv = e => { const t = e.touches ? e.touches[0] : e; if (!t) return; x = t.clientX; y = t.clientY;
    if (!raf) raf = requestAnimationFrame(() => { raf = 0; fx.style.setProperty("--mx", x + "px"); fx.style.setProperty("--my", y + "px"); }); };
